    || new RegExp(`^(?:Error: )?${marker}:`, 'm').test(detail)
    || new RegExp(`"error"\\s*:\\s*"${marker}:`).test(detail);
  return `${unavailable ? 'PROOF_UNAVAILABLE' : 'PROOF_ASSERTION_FAILED'}: ${label}\n${detail}`;
